// Generated by Scripts/embed-report-template.sh from Resources/report.html. Do not edit by hand.

/// The HTML report template, embedded so the binary needs no resource bundle at run time.
enum ReportTemplate {
    static let html = #"""
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light">
<meta name="generator" content="xcblame {{TOOL_VERSION}}">
<title>{{TITLE}}</title>
<style>
:root {
  --bg: #ffffff; --panel: #f7f7f8; --line: #e4e4e7; --line-2: #d4d4d8; --track: #ededf0;
  --ink: #111111; --ink-2: #52525b; --muted: #63636b;
  --accent: #f97316; --accent-ink: #c2410c; --accent-soft: #fff1e6;
  --good: #067647; --warn: #92400e; --bad: #b42318; --good-bg: #ecfdf3; --warn-bg: #fffaeb; --bad-bg: #fef3f2;
  --xc: #a1a1aa; --xc-2: #71717a;
  --path: #f97316; --path-ink: #111111; --wait: #8a8a93;
  --util-fill: rgba(249,115,22,.14); --util-line: #c2410c; --serial: rgba(250,178,25,.28); --idle: rgba(137,135,129,.18);
  --k1: #2a78d6; --k2: #eb6834; --k3: #1baf7a; --k4: #eda100; --k5: #e87ba4; --k6: #008300; --k7: #6250d6; --k-other: #a3a29b;
  --sans: -apple-system, "SF Pro Text", "Helvetica Neue", Inter, "Segoe UI", Arial, sans-serif;
  --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 var(--sans)}
a{color:var(--accent-ink)}
code,.mono{font-family:var(--mono);font-size:13px}
.num,td.num,th.num,.kpi .v,.act-saving{font-family:var(--mono);font-variant-numeric:tabular-nums}
td.num,th.num{text-align:right;white-space:nowrap}
h1,h2,h3,h4{margin:0;font-weight:600}
h1{font-size:20px}
h2{font-size:16px}
h3{font-size:15px;margin:16px 0 8px}
button,input{font:inherit;color:inherit}
button{background:var(--bg);border:1px solid var(--line-2);border-radius:6px;padding:1px 10px;cursor:pointer;font-size:13px}
button:hover{color:var(--accent-ink);border-color:var(--accent)}
:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
[hidden]{display:none !important}
#js-errors{margin:0;padding:8px 16px;background:var(--bad-bg);color:var(--bad);font:13px var(--mono);white-space:pre-wrap}
.wrap{max-width:1200px;margin:0 auto;padding:24px 24px 48px}
.muted,.sub{color:var(--muted)}
.sub{font-size:13.5px;font-weight:400}
.na{color:var(--ink-2);margin:4px 0}
.notes{margin:4px 0;padding-left:18px;color:var(--ink-2);font-size:14px}
.notes li{margin:2px 0;overflow-wrap:anywhere}
.footnote{margin:6px 0;color:var(--ink-2);font-size:14px}
.alert,#verify-abort{margin:8px 0;padding:6px 10px;border-left:3px solid var(--bad);background:var(--bad-bg)}
#truncation,.commit,.banner{margin:8px 0;padding:6px 10px;border-left:3px solid var(--warn);background:var(--warn-bg)}
#truncation code,.banner code{overflow-wrap:anywhere}

.top{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;padding-bottom:16px;border-bottom:1px solid var(--line)}
.brand{display:flex;align-items:center;gap:8px;font-weight:600;color:var(--ink-2)}
.mark{width:16px;height:16px;border-radius:4px;background:var(--accent)}
.meta{display:flex;flex-wrap:wrap;gap:8px;margin:0;padding:0;list-style:none}
.meta li{padding:0 10px;line-height:24px;border:1px solid var(--line);border-radius:12px;color:var(--ink-2);font-size:13px;white-space:nowrap}
.meta li[data-chip=kind],.meta li[data-chip=doctor]{border-color:var(--accent);color:var(--accent-ink)}
.meta li[data-chip=degraded]{border-color:var(--bad);color:var(--bad)}
.meta a{color:inherit;text-decoration:none}

#start-body{margin-top:24px}
#headline{margin:0;font-size:26px;line-height:1.25;font-weight:600;letter-spacing:-.01em}
#headline .slower{color:var(--bad)}
#headline .faster{color:var(--good)}
#floor,#waste,.lead{margin:6px 0 0;font-size:16px;color:var(--ink-2)}
#floor b,#waste b{color:var(--ink);font-family:var(--mono);font-weight:600}
#floor b{color:var(--accent-ink)}
ol.causes{margin:8px 0 0;padding-left:22px}
ol.causes li{margin:2px 0}
#board{display:grid;grid-template-columns:1fr 1.4fr 1fr;gap:16px;margin-top:24px}
#board.one{grid-template-columns:minmax(0,760px)}
#board.two{grid-template-columns:1fr 1.4fr}
.panel{border:1px solid var(--line);border-radius:8px;padding:16px;min-width:0}
.panel > h2{margin:0 0 12px;font-size:15px}
.panel > h2 .sub{margin-left:8px}
.stack{display:flex;height:28px;border-radius:4px;overflow:hidden;gap:1px}
.stack span{min-width:1px}
#where ul{margin:12px 0 0;padding:0;list-style:none}
#where li{display:grid;grid-template-columns:12px minmax(0,1fr) auto;gap:8px;align-items:center;padding:4px 0;border-top:1px solid var(--line);font-size:14px}
#where li:first-child{border-top:0}
#where li.xc-fold{grid-template-columns:minmax(0,1fr) auto}
#where i{width:12px;height:12px;border-radius:2px}
.nm{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#start-actions{margin:0;padding:0;list-style:none;counter-reset:a}
li.act{position:relative;padding:0 0 16px 34px;counter-increment:a}
li.act + li.act{padding-top:16px;border-top:1px solid var(--line)}
li.act:last-child{padding-bottom:0}
li.act::before{content:counter(a);position:absolute;left:0;width:24px;height:24px;border-radius:50%;background:var(--accent);color:#111111;font:600 13px/24px var(--mono);text-align:center}
li.act + li.act::before{top:16px}
.act-what{display:block;font-weight:600;overflow-wrap:anywhere}
.act-why{display:flex;flex-wrap:wrap;gap:0 14px;font-size:13.5px;color:var(--ink-2)}
.act-saving{color:var(--accent-ink);font-weight:600}
.act-fix{display:block;font-size:14px;color:var(--ink-2)}
.act-undo{display:block;margin-top:4px;font-size:13px;color:var(--muted)}
.cmd{display:flex;margin-top:8px;border:1px solid var(--line);border-radius:6px;background:var(--panel);min-width:0}
.cmd code{flex:1;padding:4px 8px;line-height:20px;overflow-x:auto;white-space:nowrap;min-width:0}
.cmd button{flex:none;border:0;border-left:1px solid var(--line);border-radius:0 6px 6px 0;background:transparent}
#hot5{font-size:14px}
#hot5 td{padding:4px 0;border-bottom:0;border-top:1px solid var(--line)}
#hot5 tr:first-child td{border-top:0}
#hot5 td.num{padding-left:8px}
#hot5 .f{display:block;font:12px var(--mono);color:var(--muted);overflow-wrap:anywhere}
.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--accent);margin-right:6px;vertical-align:1px}
.dot.off{background:transparent;box-shadow:inset 0 0 0 1px var(--line-2)}

.kpis{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));margin-top:24px;border:1px solid var(--line);border-radius:8px;overflow:hidden}
.kpi{padding:14px 16px;border-left:1px solid var(--line);min-width:0}
.kpi:first-child{border-left:0}
.kpi .l{color:var(--ink-2);font-size:13.5px}
.kpi .v{font-size:28px;line-height:36px;font-weight:600;letter-spacing:-.02em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.kpi .s{color:var(--muted);font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.kpi[data-kpi=cp] .v{color:var(--accent-ink)}
#cp-ribbon{grid-column:1 / -1;border-top:1px solid var(--line);padding:14px 16px 8px;background:var(--panel)}
.rib{position:relative;height:16px;border-radius:3px;overflow:hidden;background:var(--track)}
.rib span{position:absolute;top:0;bottom:0}
.ticks{position:relative;height:16px;margin-top:4px;font:12px/16px var(--mono);color:var(--muted)}
.ticks span{position:absolute;transform:translateX(-50%);white-space:nowrap}
.ticks span:first-child{transform:none}
.ticks span:last-child{transform:translateX(-100%)}
.facts{margin:12px 0 0;color:var(--ink-2);font-size:14px}

main{margin-top:0}
#summary{margin-bottom:32px}
details.sec-d,#details-group{border-top:1px solid var(--line)}
details.sec-d > summary,#details-group > summary{display:flex;flex-wrap:wrap;align-items:baseline;gap:0 10px;padding:12px 0;cursor:pointer;list-style:none}
details.sec-d > summary::-webkit-details-marker,#details-group > summary::-webkit-details-marker{display:none}
details.sec-d > summary::before,#details-group > summary::before{content:"";align-self:center;width:7px;height:7px;margin:0 4px 0 2px;border-right:1.5px solid var(--muted);border-bottom:1.5px solid var(--muted);transform:rotate(-45deg)}
details.sec-d[open] > summary::before,#details-group[open] > summary::before{transform:rotate(45deg)}
summary .cnt{margin-left:auto;font:13px var(--mono);color:var(--muted)}
.sec-body{padding:0 0 24px}
#details-group > section{padding:0 0 16px}
#details-group > section > h3{margin-top:4px}
.tools{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:0 0 8px;font-size:14px}
.filter{width:220px;max-width:100%;padding:3px 8px;border:1px solid var(--line-2);border-radius:6px}
details > summary{cursor:pointer}
.sec-body details > summary,.fd details > summary{color:var(--ink-2);font-size:14px;margin-top:6px}

.tscroll{overflow-x:auto}
table{border-collapse:collapse;width:100%;font-size:13.5px;font-variant-numeric:tabular-nums}
caption{text-align:left;color:var(--muted);font-size:13px;padding:0 0 4px}
th,td{padding:5px 8px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
th{font-weight:500;color:var(--muted);font-size:12.5px;white-space:nowrap}
thead th{border-bottom-color:var(--line-2)}
tbody th{color:var(--ink);font-size:13.5px;white-space:normal}
th button{border:0;background:none;padding:0;font:inherit;color:inherit}
th[aria-sort="ascending"] button::after{content:" ↑"}
th[aria-sort="descending"] button::after{content:" ↓"}
td.path{font-family:var(--mono);font-size:12.5px;overflow-wrap:anywhere;min-width:200px}
td .dir,th .dir{color:var(--muted);font-weight:400}
tbody tr[data-row].open-able{cursor:pointer}
tbody tr[data-row]:hover,tbody tr[data-row]:focus{background:var(--panel)}
tbody tr.other td:first-child{font-style:italic}
tbody tr.members td{background:var(--panel);font:12px var(--mono)}
tbody tr.members ul{margin:0;padding-left:18px;columns:2 320px}
tfoot td{color:var(--ink-2);border-bottom:0}
.more{margin-top:8px;display:flex;gap:10px;align-items:center;color:var(--muted);font-size:13px}
.topped tbody tr.beyond-top,.topped tbody tr.beyond-top + tr.members{display:none}
.sec:not([data-show-xcode="1"]) [data-xcode="1"]{display:none !important}
tr.xc-fold td,li.xc-fold{color:var(--muted);font-size:13.5px}
.bar{position:relative;display:block;height:8px;min-width:80px;border-radius:2px;background:var(--track);margin-top:6px}
.bar i{position:absolute;left:0;top:0;bottom:0;border-radius:2px;background:var(--accent)}
.bar i.g{background:var(--xc)}
.badge{display:inline-block;padding:0 6px;border:1px solid var(--line-2);border-radius:9px;font-size:12px;line-height:18px;color:var(--ink-2);white-space:nowrap}
.badge.good{color:var(--good);border-color:var(--good)}
.badge.warn{color:var(--warn);border-color:var(--warn)}
.badge.bad{color:var(--bad);border-color:var(--bad)}
.badge.path{color:var(--accent-ink);border-color:var(--accent)}
.tog{padding:0 6px;font-size:12px;margin-left:6px}
.rid{font:12px var(--mono);color:var(--muted);font-weight:400}
a.rid{color:var(--muted)}
code .ph{color:var(--muted);font-style:italic;user-select:none;-webkit-user-select:none}
.future{color:var(--warn);font-size:12.5px;margin-left:6px}
.unk{color:var(--muted)}

#findings-table tr.finding{cursor:pointer}
#findings-table tr.finding td:first-child{white-space:nowrap}
#findings-table tr.finding td:first-child::before{content:"";display:inline-block;width:6px;height:6px;margin-right:8px;border-right:1.5px solid var(--muted);border-bottom:1.5px solid var(--muted);transform:rotate(-45deg);vertical-align:2px}
#findings-table tr.finding[aria-expanded="true"] td:first-child::before{transform:rotate(45deg)}
#findings-table:not(.hk-open) tr[data-housekeeping="1"]{display:none}
tr.finding-detail > td{background:var(--panel);padding:12px 16px}
tr.hk-fold td{color:var(--ink-2);cursor:pointer}
.fd{display:grid;grid-template-columns:max-content minmax(0,1fr);gap:4px 16px;margin:0;font-size:14px}
.fd dt{color:var(--muted)}
.fd dd{margin:0;overflow-wrap:anywhere}
.fd p{margin:0 0 4px}
pre{margin:4px 0;padding:6px 9px;background:var(--bg);border:1px solid var(--line);border-radius:6px;font:12.5px var(--mono);white-space:pre-wrap;overflow-wrap:anywhere}
.plan{margin:16px 0 8px}
.plan ol{margin:4px 0 8px;padding-left:22px}
.plan li{margin:3px 0;overflow-wrap:anywhere}
.plan .note{color:var(--muted);font-size:12.5px;margin-left:6px}

.legend{display:flex;flex-wrap:wrap;gap:4px 14px;margin:0 0 8px;padding:0;list-style:none;color:var(--ink-2);font-size:13px}
.legend i{display:inline-block;width:12px;height:10px;border-radius:2px;margin-right:5px;vertical-align:-1px}
.legend i.line{height:2px;vertical-align:3px}
.legend i.hatch{background-image:repeating-linear-gradient(135deg,currentColor 0 1.5px,transparent 1.5px 4px);color:var(--wait)}
.legend i.hatch.on{background-image:repeating-linear-gradient(135deg,var(--ink) 0 1px,transparent 1px 4px)}
.canvas-wrap{position:relative;border:1px solid var(--line);border-radius:6px;overflow:hidden}
canvas{display:block;width:100%;touch-action:none;cursor:grab}
canvas:active{cursor:grabbing}
.print-img{display:none;width:100%}
#tip{position:fixed;z-index:20;pointer-events:none;max-width:360px;padding:6px 9px;border-radius:6px;background:var(--ink);color:var(--bg);font-size:13px;line-height:1.4}
#tip div:first-child{font-weight:600;overflow-wrap:anywhere}
.chart{margin:8px 0 12px}
.chart figcaption{color:var(--ink-2);font-size:14px;margin-bottom:4px}
.chart svg{display:block;width:100%;max-width:900px;height:auto}
.chart text{fill:var(--ink-2);font:12px var(--sans)}
.chart text.v{fill:var(--ink);font-variant-numeric:tabular-nums}
.chart text.at{fill:var(--muted)}
.chart text.in{fill:#ffffff;stroke:rgba(0,0,0,.55);stroke-width:2.5px;paint-order:stroke;font-weight:600}
.chart .ax{stroke:var(--line-2)}
.chart .gl{stroke:var(--line)}
.chart .b1{fill:var(--xc)}
.chart .b2{fill:var(--accent)}
.chart .band{fill:var(--warn);opacity:.18}
.chart .hl{stroke:var(--ink);stroke-width:1;opacity:.45}
.chart .fail{fill:none;stroke:var(--bad)}
.kdot{display:inline-block;width:8px;height:8px;border-radius:2px;margin-right:5px}
.mini{display:flex;flex-wrap:wrap;gap:8px 32px;margin:0 0 12px}
.mini div{display:flex;flex-direction:column}
.mini b{font:600 20px/28px var(--mono)}
.mini span{color:var(--muted);font-size:13px}

#drawer{position:fixed;top:0;right:0;bottom:0;z-index:10;width:min(620px,100vw);background:var(--bg);border-left:1px solid var(--line-2);box-shadow:-6px 0 24px rgba(0,0,0,.15);display:flex;flex-direction:column}
#drawer .dhead{display:flex;align-items:baseline;gap:10px;padding:12px 16px;border-bottom:1px solid var(--line)}
#drawer .dhead h2{overflow-wrap:anywhere}
#drawer .dhead button{margin-left:auto}
#drawer .dbody{overflow:auto;padding:10px 16px 24px}
footer{margin-top:32px;padding-top:12px;border-top:1px solid var(--line);color:var(--muted);font-size:13px}

/* xcblame:compare:css:start */
.cmp-block{margin-top:12px}
.cmp-block > summary{list-style:none}
.cmp-block > summary::-webkit-details-marker{display:none}
.cmp-block > summary > h3,.cmp-block > h3{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 10px;margin:0 0 6px}
#compare details.cmp-block > summary > h3::before{content:"▸";color:var(--muted)}
#compare details.cmp-block[open] > summary > h3::before{content:"▾"}
.cmp-block h3 small{font-weight:400;color:var(--muted);font-size:13px}
.cmp-sides{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:12px}
.cmp-side{border:1px solid var(--line);border-radius:6px;padding:10px 12px;min-width:0}
.cmp-side h3{margin:0 0 6px;display:flex;gap:8px;align-items:baseline;flex-wrap:wrap}
.cmp-side dl{display:grid;grid-template-columns:max-content 1fr;gap:2px 12px;margin:0;font-size:13.5px}
.cmp-side dt{color:var(--muted)}
.cmp-side dd{margin:0;overflow-wrap:anywhere}
.cmp-side dd.diff{font-weight:600;color:var(--warn)}
.cmp-headline{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:1px;background:var(--line);border:1px solid var(--line);border-radius:8px;overflow:hidden}
.cmp-headline > div{background:var(--bg);padding:10px 12px;min-width:0}
.cmp-label{color:var(--muted);font-size:13px;display:block}
.cmp-num{font:600 18px var(--mono);display:block}
.cmp-headline small{display:block;color:var(--ink-2);font-size:13px}
.cmp-delta.slower{color:var(--bad)}
.cmp-delta.faster{color:var(--good)}
#cmp-band,#cmp-failed{grid-column:1 / -1}
#cmp-failed{background:var(--bad-bg);color:var(--bad);font-weight:600}
.cmp-why{margin:0;padding-left:20px}
.cmp-why li{margin:2px 0}
.cmp-why .badge{margin-right:4px}
.cmp-bars{display:grid;gap:2px}
.cmp-bar-row{display:grid;grid-template-columns:minmax(120px,22%) minmax(120px,1fr) minmax(190px,34%);gap:10px;align-items:center;padding:2px 0;border-bottom:1px solid var(--line)}
.cmp-bar-row.other .cmp-key{font-style:italic}
.cmp-key{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:12.5px var(--mono)}
.cmp-val{font-size:12.5px;color:var(--ink-2);white-space:nowrap}
.cmp-track{position:relative;height:12px;background:linear-gradient(to right,transparent calc(50% - .5px),var(--line-2) calc(50% - .5px),var(--line-2) calc(50% + .5px),transparent calc(50% + .5px))}
.cmp-fill{position:absolute;top:1px;bottom:1px;min-width:1px;border-radius:2px}
.cmp-fill.pos,.cmp-mini.pos{background:var(--bad)}
.cmp-fill.neg,.cmp-mini.neg{background:var(--good)}
.cmp-tag{position:absolute;top:-2px;font-size:11px;line-height:14px;color:var(--ink-2);white-space:nowrap}
.cmp-legend{display:flex;flex-wrap:wrap;gap:14px;color:var(--ink-2);font-size:13px;margin:0 0 4px}
.cmp-legend i{display:inline-block;width:12px;height:9px;border-radius:2px;margin-right:5px}
#compare td.cmp-pos{color:var(--bad)}
#compare td.cmp-neg{color:var(--good)}
.cmp-mini{display:inline-block;height:8px;border-radius:2px;min-width:1px;vertical-align:middle;margin-right:6px}
#cmp-timeline canvas{cursor:default;touch-action:auto;margin-bottom:8px}
.cmp-axis-label{color:var(--ink-2);font-size:13px;margin:6px 0 2px}
.cmp-env-hit th{font-weight:600}
@media (max-width:640px){.cmp-bar-row{grid-template-columns:1fr;gap:2px} .cmp-val{white-space:normal}}
/* xcblame:compare:css:end */
/* xcblame:trend:css:start */
.trend-group{margin-top:14px}
.trend-group > h3{margin:0 0 8px;overflow-wrap:anywhere}
.trend-grid{display:grid;grid-template-columns:1fr;gap:12px}
.trend-series{margin:0;padding:8px 10px 6px;border:1px solid var(--line);border-radius:8px;min-width:0}
.trend-series figcaption{display:flex;flex-wrap:wrap;align-items:baseline;gap:2px 12px;margin-bottom:4px;font-variant-numeric:tabular-nums}
.trend-p50{color:var(--good);font-weight:600}
.trend-p95{color:var(--warn);font-weight:600}
.trend-svg{display:block;width:100%;max-width:640px;height:auto}
.trend-svg text{fill:var(--muted);font:10px var(--sans)}
.trend-base{stroke:var(--line-2);stroke-width:1}
.trend-line{fill:none;stroke:var(--accent);stroke-width:1.5;stroke-linejoin:round}
.trend-rule{stroke-width:1;stroke-dasharray:4 3}
.trend-rule.p50{stroke:var(--k3)}
.trend-rule.p95{stroke:var(--k4)}
.trend-svg text.trend-rule-label.p50{fill:var(--good)}
.trend-svg text.trend-rule-label.p95{fill:var(--warn)}
.trend-marker{stroke:var(--k1);stroke-width:1.25;stroke-dasharray:2 2}
.trend-svg text.trend-marker-label{fill:var(--k1)}
.trend-svg text.trend-minmax{fill:var(--ink-2)}
.trend-point{fill:var(--accent);stroke:var(--bg);stroke-width:1;cursor:pointer}
.trend-point.trend-nowall{fill:none;stroke:var(--accent)}
.trend-point:hover,.trend-point:focus{fill:var(--accent-ink);stroke:var(--ink);outline:none}
.trend-readout{min-height:17px;color:var(--ink-2);font:12px var(--mono);overflow-wrap:anywhere}
/* xcblame:trend:css:end */
/* xcblame:why:css:start */
.why-row-strip{display:flex;flex-wrap:wrap;gap:8px 16px;align-items:baseline;margin:10px 0}
#why-summary{display:flex;flex-wrap:wrap;gap:4px 18px;margin:0;padding:0;list-style:none;color:var(--ink-2);font-size:14px}
#why-unknown{padding:6px 10px;border:1px solid var(--line);border-radius:6px;font-size:14px}
#why-unknown[data-share]:not([data-share="0"]){border-color:var(--warn)}
#why-unknown code{overflow-wrap:anywhere}
#why-tabs{display:flex;gap:4px;margin:12px 0 6px;border-bottom:1px solid var(--line-2)}
#why-tabs button{border:1px solid var(--line);border-bottom:0;border-radius:6px 6px 0 0;padding:3px 10px;background:var(--panel);color:var(--ink-2)}
#why-tabs button[aria-selected="true"]{background:var(--bg);color:var(--ink);font-weight:600}
.why-rank{margin:0;padding:0;list-style:none}
.why-rank li{display:grid;grid-template-columns:2.2em minmax(0,1fr) 7em 10em;gap:2px 10px;align-items:center;padding:3px 0;border-bottom:1px solid var(--line);font-size:14px;font-variant-numeric:tabular-nums}
.why-rank .why-n{color:var(--muted);text-align:right}
.why-rank .why-secs{text-align:right}
.why-bar{height:8px;border-radius:2px;background:var(--accent);min-width:1px}
.why-rank li.why-unknown-row .why-bar{background:var(--warn)}
.why-class{margin-top:10px;border-top:1px solid var(--line);padding-top:6px}
.why-class > summary{font-weight:600;color:var(--ink)}
.why-cause{margin:8px 0 8px 12px}
.why-cause h4{margin:0 0 3px;font-size:14px;display:flex;flex-wrap:wrap;gap:4px 8px;align-items:baseline}
.why-cause .why-ev{margin:2px 0 4px;padding-left:18px;color:var(--ink-2);font-size:13px}
.why-cause .why-ev li{overflow-wrap:anywhere}
@media (max-width:640px){.why-rank li{grid-template-columns:2em minmax(0,1fr) 6em} .why-rank .why-bar-cell{display:none}}
/* xcblame:why:css:end */
/* xcblame:fixedcosts:css:start */
.fc-assumption{margin-left:6px}
.fc-tasks td{padding:4px 8px 8px 24px;background:var(--panel)}
.fc-tasks th,.fc-tasks td td{padding:1px 8px 1px 0;background:none}
.fcbar{display:grid;grid-template-columns:minmax(0,180px) 1fr minmax(0,160px);gap:10px;align-items:center;font-size:14px}
.fcbar .bar{margin:0}
#fc-total{margin:8px 0 0;color:var(--ink-2)}
/* xcblame:fixedcosts:css:end */
/* xcblame:modulegraph:css:start */
.mg-tools{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:6px 0}
.mg-hint{color:var(--muted);font-size:13px}
.mg-frame{border:1px solid var(--line);border-radius:6px;overflow:hidden;touch-action:none;cursor:grab;user-select:none;-webkit-user-select:none}
.mg-frame.mg-panning{cursor:grabbing}
svg#mg-svg{display:block;width:100%}
.mg-node rect{fill:var(--bg);stroke:var(--line-2);stroke-width:1}
.mg-node.mg-onchain rect{stroke:var(--accent);stroke-width:2}
.mg-node.mg-collapsed rect{fill:var(--panel);stroke-dasharray:4 3}
.mg-node text{fill:var(--ink);font:11.5px var(--sans);pointer-events:none}
.mg-node text.mg-sub{fill:var(--muted);font-size:10px}
.mg-node{cursor:pointer;outline:none}
.mg-node:focus rect,.mg-node:hover rect{stroke:var(--accent-ink);stroke-width:2}
.mg-badge rect{stroke:none}
.mg-variants rect{fill:var(--warn-bg)}
.mg-variants text{fill:var(--warn);font-size:10px}
.mg-macros rect{fill:var(--panel)}
.mg-macros text{fill:var(--ink-2);font-size:10px}
.mg-edge{fill:none;stroke:var(--line-2);stroke-width:1.2}
.mg-edge.mg-critical{stroke:var(--accent);stroke-width:2.6;stroke-dasharray:7 3}
.mg-arrow{fill:var(--line-2)}
.mg-arrow.mg-arrow-crit{fill:var(--accent)}
text.mg-chain-label{fill:var(--accent-ink);font:600 11.5px var(--sans)}
.mg-lists{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(260px,100%),1fr));gap:4px 18px}
.mg-lists ol,.mg-lists ul{margin:0;padding-left:20px;font-size:14px;font-variant-numeric:tabular-nums}
@media print{.mg-frame{overflow:visible} .mg-tools{display:none}}
/* xcblame:modulegraph:css:end */
.verify-run{font:12px var(--mono)}
.verify-run[data-ok="false"]{color:var(--bad)}
.verify-run[data-settle="true"]{opacity:.45}
@media (max-width:1000px){#board{grid-template-columns:1fr 1fr} #where{grid-column:1 / -1}}
@media (max-width:860px){.kpi{padding:12px} .kpi .v{font-size:22px;line-height:30px}}
@media (max-width:640px){.wrap{padding:16px 16px 32px}
#headline{font-size:21px}
.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}
.kpi{border-top:1px solid var(--line)}
.kpi:nth-child(-n+2){border-top:0}
.kpi:nth-child(odd){border-left:0}
.kpi[data-kpi=cp]{grid-column:1 / -1}
#board,#board.one{grid-template-columns:minmax(0,1fr)}
.filter{width:100%}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto !important;transition:none !important}}
@media print{#drawer,#tip,.tools,.more,.cmd button,.xc-toggle,button.tog{display:none !important}
body{font-size:12px;-webkit-print-color-adjust:exact;print-color-adjust:exact}
.wrap{max-width:none;padding:0}
canvas{display:none}
.print-img{display:block}
.cmd code{white-space:pre-wrap}
.panel,tr,.kpis{break-inside:avoid}}
</style>
</head>
<body>
<pre id="js-errors" role="alert" hidden></pre>
<div class="wrap">
<header id="top" class="top">
  <div class="brand"><span class="mark" aria-hidden="true"></span>xcblame</div>
  <h1 id="h-scheme">{{TITLE}}</h1>
  <ul id="meta" class="meta" aria-label="Build facts"></ul>
</header>
<main>
<section id="start-here" class="sec" aria-label="Start here">
  <div id="start-body"><p class="na">Loading the report data.</p></div>
</section>
<section id="summary" class="sec" aria-label="Summary">
  <div id="sum-body"></div>
</section>
<section id="timeline" class="sec"><details class="sec-d"><summary><h2>Critical path</h2><span class="sub">what the build waited on</span><span class="cnt" id="tl-count"></span></summary><div class="sec-body">
  <div class="tools"><label id="tl-all-label"><input type="checkbox" id="tl-all"> All tasks</label><button id="tl-in" aria-label="Zoom in">+</button><button id="tl-out" aria-label="Zoom out">−</button><button id="tl-reset">Reset</button></div>
  <div id="tl-body"></div>
</div></details></section>
<section id="targets" class="sec"><details class="sec-d"><summary><h2>Targets</h2><span class="sub">work done versus time waited</span><span class="cnt"></span></summary><div class="sec-body">
  <div class="tools"><input type="search" class="filter" placeholder="Filter (/)" aria-label="Filter targets"></div><div class="body"></div>
</div></details></section>
<section id="files" class="sec"><details class="sec-d"><summary><h2>Files</h2><span class="sub">slowest source files to compile</span><span class="cnt"></span></summary><div class="sec-body">
  <div class="tools"><input type="search" class="filter" placeholder="Filter (/)" aria-label="Filter files"></div><div class="body"></div>
</div></details></section>
<section id="hotspots" class="sec"><details class="sec-d"><summary><h2>Hotspots</h2><span class="sub">slowest code to type-check</span><span class="cnt"></span></summary><div class="sec-body">
  <div class="tools"><input type="search" class="filter" placeholder="Filter (/)" aria-label="Filter hotspots"></div><div class="body"></div>
</div></details></section>
<section id="findings" class="sec"><details class="sec-d" open><summary><h2>Findings</h2><span class="sub">what to change</span><span class="cnt"></span></summary><div class="sec-body">
  <div class="body"></div>
</div></details></section>
<!-- xcblame:why:start -->
<section id="why" class="sec" hidden><details class="sec-d"><summary><h2>Incremental why</h2><span class="sub">why tasks ran again</span><span class="cnt"></span></summary><div class="sec-body">
  <div id="why-body"></div>
</div></details></section>
<!-- xcblame:why:end -->
<!-- xcblame:fixedcosts:start -->
<section id="fixedcosts" class="sec" hidden><details class="sec-d"><summary><h2>Fixed costs</h2><span class="sub">paid by every build</span><span class="cnt"></span></summary><div class="sec-body">
  <div id="fc-body"></div>
</div></details></section>
<!-- xcblame:fixedcosts:end -->
<!-- xcblame:modulegraph:start -->
<section id="modulegraph" class="sec" hidden><details class="sec-d"><summary><h2>Module graph</h2><span class="sub">which targets wait on which</span><span class="cnt"></span></summary><div class="sec-body">
  <div id="mg-body"></div>
</div></details></section>
<!-- xcblame:modulegraph:end -->
<details id="details-group"><summary><h2>Details</h2><span class="sub">diagnostics, checks, environment, notes</span></summary>
<section id="diagnostics" class="sec"><h3>Diagnostics</h3><div class="body"></div></section>
<section id="environment" class="sec"><h3>Checks and environment</h3><div class="body"></div></section>
<section id="notes" class="sec"><h3>Notes</h3><div class="body"></div></section>
</details>
<!-- xcblame:compare:start -->
<section id="compare" class="sec" hidden><details class="sec-d"><summary><h2>Compare</h2><span class="sub">build b against build a</span><span class="cnt"></span></summary><div class="sec-body">
  <div id="cmp-body"></div>
</div></details></section>
<!-- xcblame:compare:end -->
<!-- xcblame:trend:start -->
<section id="trend" class="sec" hidden><details class="sec-d"><summary><h2>Trend</h2><span class="sub">build times over time</span><span class="cnt"></span></summary><div class="sec-body">
  <div id="trend-body"></div>
</div></details></section>
<!-- xcblame:trend:end -->
<!-- xcblame:verify:start -->
<section id="verify" class="sec" hidden><details class="sec-d"><summary><h2>Verify</h2><span class="sub">each change measured with and without</span><span class="cnt"></span></summary><div class="sec-body">
  <div id="verify-body"></div>
</div></details></section>
<section id="fixplan" class="sec" hidden><details class="sec-d"><summary><h2>Fix plan</h2><span class="sub">the changes, in order</span><span class="cnt"></span></summary><div class="sec-body">
  <div id="fixplan-body"></div>
</div></details></section>
<!-- xcblame:verify:end -->
</main>
<footer>Generated {{GENERATED_AT}} by xcblame {{TOOL_VERSION}}. Terms: docs/REPORT.md · xcblame rules explain &lt;id&gt;</footer>
</div>
<aside id="drawer" role="dialog" aria-modal="false" aria-labelledby="drawer-title" hidden>
  <div class="dhead"><h2 id="drawer-title" tabindex="-1"></h2><span class="muted" id="drawer-count"></span><button id="drawer-close">Close</button></div>
  <div class="dbody" id="drawer-body"></div>
</aside>
<div id="tip" role="tooltip" hidden></div>
<script type="application/json" id="xcblame-data" data-encoding="json">{{DATA}}</script>
<script>
(function () {
'use strict';
var errBox = document.getElementById('js-errors');
function reportError(text) { errBox.hidden = false; errBox.textContent += text + '\n'; }
window.onerror = function (msg, src, line, col) { reportError(String(msg) + ' (line ' + line + ':' + col + ')'); };
window.addEventListener('unhandledrejection', function (e) { reportError('unhandled rejection: ' + String(e.reason)); });

// --- helpers
function $(sel, root) { return (root || document).querySelector(sel); }
function el(tag, attrs) {
  var node = document.createElement(tag);
  if (attrs) for (var key in attrs) {
    var v = attrs[key];
    if (v == null || v === false) continue;
    if (key === 'class') node.className = v;
    else if (key === 'text') node.textContent = v;
    else if (key.slice(0, 2) === 'on') node.addEventListener(key.slice(2), v);
    else node.setAttribute(key, v === true ? '' : String(v));
  }
  for (var i = 2; i < arguments.length; i++) {
    var kid = arguments[i];
    if (kid == null || kid === false) continue;
    if (Array.isArray(kid)) appendAll(node, kid);
    else node.append(kid);
  }
  return node;
}
function tx(tag, cls, text) { return el(tag, { class: cls, text: text }); }
function appendAll(node, list) { list.forEach(function (k) { if (Array.isArray(k)) appendAll(node, k); else if (k != null && k !== false) node.append(k); }); }
function fill(sel, kids) { var n = $(sel); n.replaceChildren.apply(n, kids.filter(Boolean)); return n; }
var nf = new Intl.NumberFormat('en-US');
function int(n) { return nf.format(n); }
function secs(s) {
  if (s == null) return '';
  var a = Math.abs(s);
  if (a >= 100) return s.toFixed(0) + ' s';
  if (a >= 10) return s.toFixed(1) + ' s';
  if (a >= 1) return s.toFixed(2) + ' s';
  return (s * 1000).toFixed(0) + ' ms';
}
function s1(s) { return s.toFixed(1) + ' s'; }
function msText(v) { return v >= 1000 ? (v / 1000).toFixed(2) + ' s' : v.toFixed(v < 10 ? 1 : 0) + ' ms'; }
function pct(x) { return (x * 100).toFixed(1) + '%'; }
function pct0(x) { return Math.round(Math.abs(x) * 100) + ' %'; }
function bytes(n) { return n >= 1073741824 ? (n / 1073741824).toFixed(0) + ' GB' : n >= 1048576 ? (n / 1048576).toFixed(0) + ' MB' : int(n) + ' B'; }
function plural(n, word) { return int(n) + ' ' + word + (n === 1 ? '' : 's'); }
function noteAbout(arrays, word) {
  var all = [];
  arrays.forEach(function (a) { if (a) all = all.concat(a); });
  if (!word) return all[0] || null;
  var w = word.toLowerCase();
  for (var i = 0; i < all.length; i++) if (all[i].toLowerCase().indexOf(w) >= 0) return all[i];
  return null;
}
function failedCheck(id) { return (D.validation.checks || []).filter(c => c.id === id && c.status === 'fail')[0]; }
function unknown(reason, check) {
  var f = check && failedCheck(check);
  if (f) return 'unavailable because ' + f.id + ' failed' + (f.detail ? ': ' + f.detail : '');
  return 'unknown (' + (reason || 'not measured') + ')';
}
function unk(reason, short) { return el('span', { class: 'unk', title: reason }, short || 'unknown'); }
function naLine(note) { return tx('p', 'na', 'not applicable: ' + (note || 'no data for this section')); }
function withheldLine(note) { return tx('p', 'na', 'unavailable because ' + (note || 'the rows were withheld')); }
function shown(n, total, share, measure) {
  return 'shown ' + int(n) + ' of ' + int(total) + (share != null ? ' (' + pct(share) + ' of ' + measure + ')' : '');
}
function setCounts(id, total, shownRows) {
  var s = document.getElementById(id);
  s.setAttribute('data-total', String(total));
  s.setAttribute('data-shown', String(shownRows));
}
function cnt(id, text) { var c = $('#' + id + ' .cnt'); if (c) c.textContent = text; }
function cssVar(name) { return getComputedStyle(document.documentElement).getPropertyValue(name).trim(); }
function copyText(text, button) {
  function done(ok) { if (button) { var old = button.textContent; button.textContent = ok ? 'Copied' : 'Select and copy'; setTimeout(function () { button.textContent = old; }, 1200); } }
  function fallback() {
    var area = el('textarea'); area.value = text; document.body.append(area); area.select();
    var ok = false; try { ok = document.execCommand('copy'); } catch (e) { ok = false; }
    area.remove(); done(ok);
  }
  if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(text).then(function () { done(true); }, fallback);
  else fallback();
}
document.addEventListener('click', function (e) {
  var b = e.target.closest && e.target.closest('button[data-copy]');
  if (b) { e.stopPropagation(); copyText(b.getAttribute('data-copy'), b); }
});
function xcToggle(n) {
  return el('button', { class: 'xc-toggle', 'aria-pressed': 'false', 'data-n': n, text: 'Show Xcode work (' + int(n) + ')', onclick: function () {
    var s = this.closest('section'), on = s.getAttribute('data-show-xcode') !== '1';
    s.setAttribute('data-show-xcode', on ? '1' : '0');
    s.querySelectorAll('.xc-toggle').forEach(function (b) {
      b.setAttribute('aria-pressed', String(on)); b.textContent = (on ? 'Hide' : 'Show') + ' Xcode work (' + int(+b.getAttribute('data-n')) + ')';
    });
  } });
}

// --- generic sortable, paged table with roving tabindex
// Above the dispatch: compare and trend use it too. `top` folds later rows behind "Show all N rows"; `xcode(r)` rows fold into `tr.xc-fold`.
var PAGE = 200;
var tables = [];
function makeTable(o) {
  var top = o.top || PAGE;
  var state = { sort: o.sort == null ? -1 : o.sort, dir: o.dir || 'descending', filter: '', limit: PAGE, open: {}, expanded: false };
  var thead = el('thead'), tbody = el('tbody'), tfoot = o.footer ? el('tfoot') : null;
  var table = el('table', null, o.caption ? tx('caption', null, o.caption) : null, thead, tbody, tfoot);
  var wrap = el('div', { class: 'tscroll' }, table);
  var status = el('span'), more = tx('button', 'show-all', 'Show all rows');
  var moreBox = el('div', { class: 'more' }, status, more);
  var headRow = el('tr');
  o.columns.forEach(function (c, i) {
    var th = el('th', { scope: 'col', class: c.num ? 'num' : null, title: c.tip || null });
    if (c.sort) {
      th.setAttribute('aria-sort', i === state.sort ? state.dir : 'none');
      th.append(el('button', { text: c.label, onclick: function () {
        if (state.sort === i) state.dir = state.dir === 'descending' ? 'ascending' : 'descending';
        else { state.sort = i; state.dir = c.num ? 'descending' : 'ascending'; }
        headRow.children.forEach(function (h, j) { if (h.hasAttribute('aria-sort')) h.setAttribute('aria-sort', j === state.sort ? state.dir : 'none'); });
        render();
      } }));
    } else th.textContent = c.label;
    headRow.append(th);
  });
  thead.append(headRow);
  more.addEventListener('click', function () { if (!state.expanded) state.expanded = true; else state.limit += PAGE; render(); });
  function rowsNow() {
    var rows = o.rows;
    if (state.filter && o.text) { var f = state.filter.toLowerCase(); rows = rows.filter(r => o.text(r).toLowerCase().indexOf(f) >= 0); }
    if (state.sort >= 0) {
      var c = o.columns[state.sort], sign = state.dir === 'ascending' ? 1 : -1;
      rows = rows.slice().sort(function (a, b) {
        var x = c.sort(a), y = c.sort(b);
        if (x == null && y == null) return 0; if (x == null) return 1; if (y == null) return -1;
        return (x < y ? -1 : x > y ? 1 : 0) * sign;
      });
    }
    if (o.pin) rows = rows.filter(r => !o.pin(r)).concat(rows.filter(o.pin));
    return rows;
  }
  function render() {
    var rows = rowsNow(), frag = document.createDocumentFragment(), count = Math.min(rows.length, state.limit), nx = 0, sx = 0, at = 0;
    for (var i = 0; i < count; i++) {
      var r = rows[i], xc = o.xcode && o.xcode(r);
      if (o.group) { var g = o.group(r, rows[i - 1], state); if (g) frag.append(g); }
      if (xc) { nx++; sx += o.xcodeSecs ? o.xcodeSecs(r) || 0 : 0; } else at++;
      var tr = el('tr', Object.assign({ 'data-row': i, tabindex: i === 0 ? '0' : '-1', 'data-xcode': xc ? '1' : null,
        class: (o.rowClass ? o.rowClass(r) : '') + (o.open ? ' open-able' : '') + (!xc && at > top ? ' beyond-top' : '') }, o.rowAttrs ? o.rowAttrs(r) : null));
      o.columns.forEach(function (c) {
        var td = el(c.head ? 'th' : 'td', { class: (c.num ? 'num ' : '') + (typeof c.cls === 'function' ? c.cls(r) : (c.cls || '')), scope: c.head ? 'row' : null });
        var v = c.cell(r, td);
        if (v != null) td.append(v);
        tr.append(td);
      });
      tr._row = r;
      frag.append(tr);
      if (o.expand && state.open[o.key(r)]) frag.append(o.expand(r));
    }
    if (nx) frag.append(el('tr', { class: 'xc-fold' }, el('td', { colspan: String(o.columns.length) },
      'Xcode\'s own work: ' + plural(nx, 'row') + (sx ? ', ' + secs(sx) : '') + ' ', xcToggle(nx))));
    tbody.replaceChildren(frag);
    if (tfoot) tfoot.replaceChildren.apply(tfoot, o.footer(rows));
    var mine = rows.length - nx, visible = state.expanded ? count - nx : Math.min(count - nx, top);
    wrap.classList.toggle('topped', !state.expanded);
    status.textContent = visible < mine ? 'Showing ' + int(visible) + ' of ' + int(mine) + ' rows.' : 'Showing all ' + int(mine) + ' rows.';
    more.textContent = !state.expanded ? 'Show all ' + int(mine) + ' rows' : 'Show ' + int(Math.min(PAGE, rows.length - count)) + ' more (' + int(rows.length) + ' rows in all)';
    more.hidden = visible >= mine && count >= rows.length;
    moreBox.hidden = mine <= top && count >= rows.length;
    if (o.onRender) o.onRender(state, table);
    if (o.onShown) o.onShown(count);
  }
  tbody.addEventListener('keydown', function (e) {
    var tr = e.target.closest && e.target.closest('tr[data-row]');
    if (!tr || e.target !== tr) return;
    var step = e.key === 'ArrowDown' ? 1 : e.key === 'ArrowUp' ? -1 : 0;
    if (step) {
      var rows = Array.prototype.slice.call(tbody.querySelectorAll('tr[data-row]')), at = rows.indexOf(tr), next = rows[at + step];
      if (next) { tr.tabIndex = -1; next.tabIndex = 0; next.focus(); }
      e.preventDefault();
    } else if (e.key === 'Enter' || e.key === ' ') {
      if (o.open) o.open(tr._row); else if (o.expand) toggle(tr._row);
      e.preventDefault();
    }
  });
  tbody.addEventListener('click', function (e) {
