    CP && CP.waits.length ? el('li', null, el('i', { class: 'hatch' }), 'wait: nothing on the path ran') : null,
    T.utilization ? el('li', null, el('i', { style: 'background: var(--util-line)' }), 'tasks running at once') : null,
    T.serialThresholdLanes != null ? el('li', null, el('i', { class: 'line', style: 'background: var(--ink-2)' }), 'serial threshold (' + T.serialThresholdLanes + ')') : null,
    T.serialStretches && T.serialStretches.length ? el('li', null, el('i', { style: 'background: var(--serial)' }), 'serial: almost one task at a time') : null,
    T.idleGaps && T.idleGaps.length ? el('li', null, el('i', { style: 'background: var(--idle)' }), 'idle: nothing running') : null));
