// --- lazy rendering, hash, keyboard, print
var sections = [
  { id: 'summary', render: renderSummary }, { id: 'timeline', render: renderTimeline }, { id: 'targets', render: renderTargets },
  { id: 'files', render: renderFiles }, { id: 'hotspots', render: renderHotspots }, { id: 'findings', render: renderFindings },
