}
try { chips(); } catch (e) { reportError('header: ' + (e && e.stack || e)); }
try { startReport(); } catch (e) { reportError('start here: ' + (e && e.stack || e)); }
ensure('summary');
ensure('findings');
performance.mark('xcblame:first-paint');
document.body.setAttribute('data-first-paint', String(Math.round(performance.now())));
var rest = sections.filter(s => !done[s.id]).map(s => s.id);
(function idle(i) { if (i < rest.length) setTimeout(function () { ensure(rest[i]); idle(i + 1); }, 0); else allRendered(); })(0);
function allRendered() {
  document.body.setAttribute('data-rendered', 'all');
  markVisible();
  var t = location.hash.length > 1 && !/^#target=/.test(location.hash) && document.getElementById(location.hash.slice(1));
  if (t && t.scrollIntoView) t.scrollIntoView();
}
function reveal(t) {
  for (var n = t; n; n = n.parentElement) if (n.tagName === 'DETAILS') n.open = true;
  if (t._flip && t.getAttribute('aria-expanded') !== 'true') t._flip();
  if (t.getAttribute('data-housekeeping') === '1') $('#findings-table').classList.add('hk-open');
