  if (tag === 'input' || tag === 'textarea' || e.target.isContentEditable) return;
  var inputs = Array.prototype.filter.call(document.querySelectorAll('.filter'), shownNow);
  var best = inputs.filter(function (i) { var r = i.getBoundingClientRect(); return r.top >= 0 && r.top < window.innerHeight; })[0] || inputs[0];
